"""Valeurs de l'oracle du § 7.3 du brief M4b-2 — données seules, recopiées telles
quelles.

Calculées en conception avant écriture par un oracle en arithmétique exacte et par un
prototype flottant, qui concordent (en-tête du brief). Nombres écrits comme en Python,
à douze décimales ; tolérance **relative** ``1e−9·max(1, |x|)`` (§ 7.0), portée par
:func:`fixtures.scoring.close`. Statuts, motifs, effectifs, booléens, masques exacts.

Par cas (§ 7.3) : préfixe ``m``, ``K``, ``b_0``, ``t*_0``, écart d'arrivée,
``(θ_bas, θ_haut)`` en numéros de convention ; les segments admis (``k``, ``b_k``,
``b_{k+1}``, ``d_r(π_k)``, ``d_r(π_{k+1})``, classe, temps sous ``E`` / ``M θc`` /
``(M+U) θc``) ; les segments de temps nul sous ``M θ1 … M θ5`` ; les points de
``C_k`` et les éléments de ``K`` (libellé, abscisse, motif, ``T`` sous ``E`` /
``M θc``) ; par scénario, les ``p_i``, en usage les ``P_k``, puis sous ``E`` et, en
usage, sous ``M θc`` les métriques du support, le diagnostic, les agrégats de ``C_k``
et la cible d'usage ; les cinq enveloppes (support, puis montée, plat, descente,
mixte) quand le § 7.3 les liste. « Régimes sans référence » : identique à Régimes
(observation et contrôle), sans usage.

Utilisées par les ``tests/test_backtest_scoring_*.py``.
"""

from dataclasses import dataclass

from mountain_perf.schemas import RegimeClass, Unavailability

A, F, D, X = (
    RegimeClass.ASCENT,
    RegimeClass.FLAT,
    RegimeClass.DESCENT,
    RegimeClass.MIXED,
)
INSUF = Unavailability.INSUFFICIENT_SUPPORT
ZERO = Unavailability.ZERO_TIME
ERR = Unavailability.MODEL_ERROR
AMBIGUOUS = Unavailability.AMBIGUOUS
ABSENT = Unavailability.ABSENT
TANGENT = Unavailability.UNDEFINED_TANGENT


@dataclass(frozen=True)
class M:
    """Une valeur de M4b-1 : ``valeur (effectif)`` ou ``motif (effectif)``."""

    value: float | None
    motif: Unavailability | None
    count: int


@dataclass(frozen=True)
class S:
    """Les métriques d'un support : ``L``, ``A``, ``W``, ``B``, ``C_comp``."""

    level: M
    dispersion: M
    within: M
    between: M
    compensation: M


@dataclass(frozen=True)
class G:
    """Le diagnostic de D5.5 : masque, ``L`` et ``A`` du sous-support."""

    mask: tuple[bool, ...]
    level: M
    dispersion: M


@dataclass(frozen=True)
class C:
    """Les agrégats de ``C_k`` : ``max |C_k|``, ``max C_k``, ``min C_k``, drapeau."""

    max_abs: M
    max: M
    min: M
    model_error: bool


@dataclass(frozen=True)
class T:
    """La cible d'usage : ``q_usage``, ``q | préfixe``, comparables, poids."""

    q_usage: M
    q_prefix: M
    comparable: tuple[bool, ...]
    weights: tuple[float, ...] | None


@dataclass(frozen=True)
class K:
    """Les scores d'une horloge ; ``passages`` et ``target`` en usage seulement."""

    support: S
    diagnostic: G | None
    passages: C | None
    target: T | None


@dataclass(frozen=True)
class E:
    """Une enveloppe à valeurs, sans motif : ``[lower ; upper]``, ``min |L|``."""

    lower: float
    upper: float
    min_abs: float


@dataclass(frozen=True)
class U:
    """Un scénario : ``p_i``, ``P_k`` des points et de ``K`` (usage), scores sous
    ``E`` et sous ``M θc`` (usage), enveloppes (support, puis les quatre classes)
    quand le § 7.3 les liste."""

    segment_s: tuple[float, ...]
    point_s: tuple[float, ...] | None
    target_s: tuple[float, ...] | None
    elapsed: K
    moving: K | None
    envelopes: tuple[E | None, ...] | None


@dataclass(frozen=True)
class R:
    """Un segment admis : ``k``, bornes, ``d_r``, classe, temps sous ``E``,
    ``M θc``, ``(M+U) θc``."""

    index: int
    start_m: float
    end_m: float
    realized_start_m: float
    realized_end_m: float
    regime_class: RegimeClass
    times_s: tuple[float, float, float]


@dataclass(frozen=True)
class P:
    """Un point de ``C_k`` ou un élément de ``K`` : libellé, abscisse, motif, ``T``
    sous ``E`` et ``M θc``."""

    label: str
    distance_m: float
    motif: Unavailability | None
    times_s: tuple[float, float] | None


@dataclass(frozen=True)
class V:
    """Les valeurs d'un cas."""

    prefix: int
    segment_count: int
    origin_m: float
    origin_s: float | None
    gap_m: float | None
    conventions: tuple[int, int] | None
    segments: tuple[R, ...]
    zero_time: dict[str, list[int]]
    points: tuple[P, ...]
    targets: tuple[P, ...]
    usage: U
    control: U


